const test = require('node:test');
const assert = require('node:assert');
const cart = require('../src/cart.js');

test('subtotal includes every line item', () => {
  const items = [{ price: 2, qty: 3 }, { price: 5, qty: 1 }];
  assert.strictEqual(cart.subtotal(items), 11);
});

test('total applies 10 percent discount at 100 or more', () => {
  const items = [{ price: 50, qty: 1 }, { price: 50, qty: 1 }];
  assert.strictEqual(cart.total(items), 90);
});

test('money formats plain dollars', () => {
  assert.strictEqual(cart.money(90), '$90');
});

